function cut(ev){if(blocked(ev)||!S().selected.length)return;copy(ev);const ids=new Set(clip.nodes.map(n=>n.id));cutData={project:P().id,data:JSON.parse(JSON.stringify(clip)),edges:JSON.parse(JSON.stringify(P().edges.filter(e=>ids.has(e.from)||ids.has(e.to)||S().selected.includes(e.id))))};FWCanvas.remove();F().toast('已剪切，可撤销恢复')}
