function rotate(id,angle){F().transact('旋转图片',()=>{const n=P().nodes.find(x=>x.id===id),cx=n.x+n.w/2,cy=n.y+n.h/2;if(n.crop){const c=n.crop;n.crop=angle>0?{x:1-c.y-c.h,y:c.x,w:c.h,h:c.w}:{x:c.y,y:1-c.x-c.w,w:c.h,h:c.w}}n.rotation=((n.rotation||0)+angle+360)%360;[n.w,n.h]=[n.h,n.w];n.x=cx-n.w/2;n.y=cy-n.h/2})}
function openImage(id){const n=P().nodes.find(x=>x.id===id);if(!n)return;const el=document.createElement('div');el.className='fw-dialog-backdrop image-viewer';el.innerHTML=`<section role="dialog" aria-modal="true" aria-label="图片查看器"><header><span>图片</span><span>适应窗口</span><button data-original>查看原图</button><button data-close aria-label="关闭图片">${i('close')}</button></header><div class="image-viewer-content"></div></section>`;document.body.append(el);let original=false;const show=()=>{const view=el.querySelector('.image-viewer-content');const ratio=n.w/n.h,ww=Math.min(innerWidth*.8,innerHeight*.7*ratio),hh=ww/ratio;view.style.cssText=`position:relative;width:${ww}px;height:${hh}px;overflow:hidden`;if(original){view.style.cssText='position:relative;max-width:80vw;max-height:70vh;display:flex;align-items:center;justify-content:center;overflow:visible';view.innerHTML=`<img src="${e(n.src)}" alt="图片原图" style="transform:rotate(${n.rotation||0}deg);max-width:70vw;max-height:65vh">`}else view.innerHTML=FWCanvas.imageMarkup({...n,w:ww,h:hh});el.querySelector('[data-original]').textContent=original?'查看画布效果':'查看原图'};show();el.querySelector('[data-original]').onclick=()=>{original=!original;show()};const close=()=>{el.remove();$('canvasEngine').focus()};el.querySelector('[data-close]').onclick=close;el.onkeydown=ev=>{if(ev.key==='Escape'){ev.stopPropagation();close()}};el.querySelector('[data-close]').focus()}

